import React from 'react';

import { useNavigate } from 'react-router-dom';

import BGU from '@components/BGU';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import { round } from '@helpers/mathHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohContainer from '@ui-kit/layout/Container';
import PohList from '@ui-kit/List';
import PohTabs from '@ui-kit/Tabs';

import { getRecipesWithCategories } from '../@services/recipes.service';
import { IRecipesGroup } from '../@types/recipes.types';

const RecipesListPage: React.FC = () => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IRecipesGroup[]>([]);

  const navigate = useNavigate();

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const res = await getRecipesWithCategories();
      setData(res);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  React.useEffect(() => {
    load();
  }, [load]);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  return (
    <div>
      <PohBreadcrumbs data={[{ href: '/recipes', text: 'Рецепты', active: true }]} />

      <PohContainer>
        <PageHeader title="Рецепты">
          <PohButton
            variant={ButtonVariant.Success}
            size={ButtonSize.Small}
            onClick={() => {
              navigate(`/recipes/add`);
            }}
          >
            Добавить
          </PohButton>
        </PageHeader>
        <PohTabs
          useHash
          tabs={data.map((rec) => {
            return {
              key: rec.id,
              title: rec.name,
              content: (
                <div>
                  <PohList
                    flush
                    data={rec.items.map((recipe) => {
                      return {
                        key: recipe.id,
                        action: true,
                        onClick: () => {
                          navigate(`/recipes/${recipe.id}`);
                        },
                        children: (
                          <div className="d-flex align-items-center ms-n2 ny-n3">
                            <PohAva
                              colorize
                              src={recipe.photo}
                              alt={recipe.name}
                              className="me-2"
                            />
                            <div>
                              <strong title={recipe.promo}>{recipe.name}</strong>
                              <small className="ms-2 text-muted">&nbsp;</small>
                              <small className="d-block text-muted">{recipe.promo}</small>
                            </div>
                            <BGU
                              portion={round(recipe.amount, 0)}
                              energy={round(recipe.energy, 0)}
                              protein={round(recipe.protein, 0)}
                              fat={round(recipe.fat, 0)}
                              carbohydrates={round(recipe.carbs, 0)}
                              unit="в порции"
                              className="ms-auto"
                            />
                          </div>
                        ),
                      };
                    })}
                  />
                </div>
              ),
            };
          })}
        />
      </PohContainer>
    </div>
  );
};

export default RecipesListPage;
